     3→import {useMutation, useQuery, useQueryClient} from '@tanstack/react-query';
     4→import apiClient from '@/lib/api/client';
     5→import {mapCursorDictionaryResponse} from '@/lib/api/dictionary-mapper';
     6→import type {
     7→    BackendCursorResponse,
     8→    CompileResult,
     9→    CursorPaginatedResponse,
    10→    Dictionary,
    11→    DictionaryOverviewResponse,
    12→    DictionaryType,
    13→    DictionaryWithId,
    14→} from '@/types';
    15→
    16→// ========================================
    17→// Query Keys
    18→// ========================================
    19→
    20→export const analysisKeys = {
    21→    all: ['analysis'] as const,
    22→    dictionaries: () => [...analysisKeys.all, 'dictionaries'] as const,
    23→    dictionaryList: (type: DictionaryType, cursor?: string | null, search?: string) =>
    24→        [...analysisKeys.dictionaries(), type, {cursor, search}] as const,
    25→    dictionaryOverview: () => [...analysisKeys.all, 'overview'] as const,
    26→};
    27→
    28→// ========================================
    29→// Dictionary List Hooks (Cursor-based)
    30→// ========================================
    31→
    32→interface DictionaryListParams {
    33→    type: DictionaryType;
    34→    cursor?: string | null;
    35→    pageSize?: number;
    36→    search?: string;
    37→    searchField?: 'all' | 'keyword' | 'value';
    38→    wordMatch?: boolean;
    39→}
    40→
    41→export function useDictionaries(params: DictionaryListParams) {
    42→    const {type, cursor = null, pageSize = 20, search, wordMatch = false} = params;
    43→
    44→    return useQuery({
    45→        queryKey: analysisKeys.dictionaryList(type, cursor, search),
    46→        queryFn: async (): Promise<CursorPaginatedResponse<Dictionary>> => {
    47→            // If search is provided, use search endpoint (returns array)
    48→            if (search && search.trim()) {
    49→                const response = await apiClient.get<DictionaryWithId[]>(
    50→                    `/api/v1/dictionary/${type}/search`,
    51→                    {
    52→                        params: {
    53→                            word: search,
    54→                            isMatch: wordMatch,
    55→                        },
    56→                    }
    57→                );
    58→                // Convert search results to cursor response format
    59→                const items = response.data;
    60→                return {
    61→                    items: items.map((item) => ({
    62→                        id: item.id,
    63→                        type: item.dictionary.type,
    64→                        keyword: item.dictionary.keyword,
    65→                        value: item.dictionary.value ?? '',
    66→                        createdAt: item.dictionary.createdTime,
    67→                        updatedAt: item.dictionary.updatedTime,
    68→                    })),
    69→                    total: items.length,
    70→                    nextCursor: null,
    71→                    hasNext: false,
    72→                };
    73→            }
    74→
    75→            // Cursor-based list endpoint - avoids ES from+size 10,000 limit
    76→            const response = await apiClient.get<BackendCursorResponse>(
    77→                `/api/v1/dictionary/${type}/cursor`,
    78→                {
    79→                    params: {
    80→                        size: pageSize,
    81→                        ...(cursor && {cursor}),
    82→                    },
    83→                }
    84→            );
    85→            return mapCursorDictionaryResponse(response.data);
    86→        },
    87→        staleTime: 30000, // 30 seconds
    88→    });
    89→}
    90→
    91→// ========================================
    92→// Dictionary CRUD Hooks
    93→// ========================================
    94→
    95→interface CreateDictionaryParams {
    96→    type: DictionaryType;
    97→    keyword?: string | null;
    98→    value?: string | null;
    99→}
   100→
   101→export function useCreateDictionary() {
   102→    const queryClient = useQueryClient();
   103→
   104→    return useMutation({
   105→        mutationFn: async (params: CreateDictionaryParams) => {
   106→            const response = await apiClient.post(
   107→                '/api/v1/dictionary',
   108→                {
   109→                    keyword: params.keyword,
   110→                    type: params.type,
   111→                    value: params.value,
   112→                }
   113→            );
   114→            return response.data;
   115→        },
   116→        onSuccess: (_, variables) => {
   117→            queryClient.invalidateQueries({
   118→                queryKey: analysisKeys.dictionaryList(variables.type),
   119→            });
   120→        },
   121→    });
   122→}
   123→
   124→interface UpdateDictionaryParams {
   125→    type: DictionaryType;
   126→    id: string;
   127→    keyword?: string | null;
   128→    value?: string | null;
   129→}
   130→
   131→export function useUpdateDictionary() {
   132→    const queryClient = useQueryClient();
   133→
   134→    return useMutation({
   135→        mutationFn: async (params: UpdateDictionaryParams) => {
   136→            const response = await apiClient.put(
   137→                `/api/v1/dictionary/${params.id}`,
   138→                {
   139→                    keyword: params.keyword ?? '',
   140→                    type: params.type,
   141→                    value: params.value,
   142→                }
   143→            );
   144→            return response.data;
   145→        },
   146→        onSuccess: (_, variables) => {
   147→            queryClient.invalidateQueries({
   148→                queryKey: analysisKeys.dictionaryList(variables.type),
   149→            });
   150→        },
   151→    });
   152→}
   153→
   154→interface DeleteDictionaryParams {
   155→    type: DictionaryType;
   156→    ids: string[];
   157→}
   158→
   159→export function useDeleteDictionary() {
   160→    const queryClient = useQueryClient();
   161→
   162→    return useMutation({
   163→        mutationFn: async (params: DeleteDictionaryParams) => {
   164→            // Backend only supports single delete, so we delete in parallel
   165→            await Promise.all(
   166→                params.ids.map(id =>
   167→                    apiClient.delete(`/api/v1/dictionary/${id}`)
   168→                )
   169→            );
   170→        },
   171→        onSuccess: (_, variables) => {
   172→            queryClient.invalidateQueries({
   173→                queryKey: analysisKeys.dictionaryList(variables.type),
   174→            });
   175→        },
   176→    });
   177→}
   178→
   179→// ========================================
   180→// Dictionary Overview Hook
   181→// ========================================
   182→
   183→export function useDictionaryOverview() {
   184→    return useQuery({
   185→        queryKey: analysisKeys.dictionaryOverview(),
   186→        queryFn: async (): Promise<DictionaryOverviewResponse> => {
   187→            const response = await apiClient.get<DictionaryOverviewResponse>(
   188→                '/api/v1/dictionary/last-modified'
   189→            );
   190→            return response.data;
   191→        },
   192→        staleTime: 30000, // 30 seconds
   193→    });
   194→}
   195→
   196→// ========================================
   197→// Dictionary Compile Hook
   198→// ========================================
   199→
   200→interface CompileDictionaryParams {
   201→    types: DictionaryType[];
   202→}
   203→
   204→export function useCompileDictionary() {
   205→    const queryClient = useQueryClient();
   206→
   207→    return useMutation({
   208→        mutationFn: async (params: CompileDictionaryParams): Promise<CompileResult[]> => {
   209→            const {types} = params;
   210→
   211→            // If all 8 types are selected, use the bulk compile endpoint
   212→            if (types.length === 8) {
   213→                const response = await apiClient.post<CompileResult[]>(
   214→                    '/api/v1/dictionary/compile'
   215→                );
   216→                return response.data;
   217→            }
   218→
   219→            // Otherwise, compile each type individually in parallel
   220→            const results = await Promise.all(
   221→                types.map(async (type) => {
   222→                    const response = await apiClient.post<CompileResult>(
   223→                        `/api/v1/dictionary/compile/${type}`
   224→                    );
   225→                    return response.data;
   226→                })
   227→            );
   228→            return results;
   229→        },
   230→        onSuccess: () => {
   231→            // Invalidate overview to refresh lastModified times
   232→            queryClient.invalidateQueries({
   233→                queryKey: analysisKeys.dictionaryOverview(),
   234→            });
   235→        },
   236→    });
   237→}
